UPDATE roadmap_skills SET label = 'Viết', note = 'Với mỗi mục ngữ pháp: test = 10 câu mình ra (điền hoặc sửa lỗi) + soát 3 bài viết gần nhất. Đạt khi ≥ 9/10 và 0 lỗi mục đó trong 3 bài viết. Cột "cách test" dưới đây ghi dạng câu mình sẽ ra.' WHERE code = 'viet';
UPDATE roadmap_skills SET label = 'Nói', note = 'Cách test khi mình không nghe được audio: ghi âm trên APEUni, dùng phần chấm từng từ (từ xanh / vàng / đỏ) để thấy âm nào máy không nhận — phần này tin được để phát hiện lỗi âm, dù điểm tổng không tin. Với trôi chảy: ghi âm, nghe lại, tự đếm số lần ngắt và "ừm". Với ngữ pháp khi nói: ghi âm 2 phút rồi tự chép lại nguyên văn, gửi mình chấm như bài viết.' WHERE code = 'noi';

